", "is_optional": false}, {"sort_order": 5, "quantity": 0.33, "unit": "cup", "name": "mayonnaise", "prep_note": null, "is_optional": false}, {"sort_order": 6, "quantity": 0.5, "unit": "cup", "name": "cotija", "prep_note": "crumbled, divided", "is_optional": false}, {"sort_order": 7, "quantity": 2.0, "unit": "tbsp", "name": "lime juice", "prep_note": null, "is_optional": false}, {"sort_order": 8, "quantity": 1.0, "unit": "tsp", "name": "chili powder", "prep_note": null, "is_optional": false}, {"sort_order": 9, "quantity": 0.25, "unit": "cup", "name": "fresh cilantro", "prep_note": "chopped", "is_optional": false}, {"sort_order": 10, "quantity": 1.0, "unit": "tsp", "name": "salt", "prep_note": null, "is_optional": false}], "steps": ["Melt butter in a large skillet over medium-high heat. Add corn in an even layer and cook 6-8 min without stirring much, until browned in spots.", "Add garlic and jalapeno for 30 sec.", "Take the pan off the heat. Stir in mayonnaise, half the cotija, lime juice, chili powder, cilantro, and salt.", "Spoon into cups and top with remaining cotija and an extra dusting of chili powder. Serve warm."]}, {"slug": "tacos-al-pastor", "title": "Tacos al Pastor", "cuisine": "Mexican", "prep_time_min": 30, "cook_time_min": 20, "servings": 4, "spice_level": 2, "cookware": ["Skillet", "Blender"], "notes": "Slice the pork thin so the marinade penetrates and the edges crisp.", "ingredients": [{"sort_order": 1, "quantity": 2.0, "unit": "lb", "name": "pork shoulder", "prep_note": "sliced 1/4 inch thick", "is_optional": false}, {"sort_order": 2, "quantity": 4.0, "unit": null, "name": "guajillo chile", "prep_note": "stemmed and seeded", "is_optional": false}, {"sort_order": 3, "quantity": 2.0, "unit": null, "name": "ancho chile", "prep_note": "stemmed and seeded", "is_optional": false}, {"sort_order": 4, "quantity": 2.0, "unit": "tbsp", "name": "achiote paste", "prep_note": null, "is_optional": false}, {"sort_order": 5, "quantity": 0.5, "unit": "cup", "name": 